import{c as e,U as d,j as a,m as l}from"./chunks/framework.DQFmIr4R.js";const p=JSON.parse('{"title":"压缩","description":"","frontmatter":{},"headers":[],"relativePath":"zh/specification/compression.md","filePath":"zh/specification/compression.md","lastUpdated":1782214112000}'),o={name:"zh/specification/compression.md"};function r(i,t,c,h,n,s){return d(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="压缩" tabindex="-1">压缩 <a class="header-anchor" href="#压缩" aria-label="Permalink to “压缩”">​</a></h1><p>压缩在 A区和 B区构建之后、S-Box 置换混淆之前执行。</p><h2 id="压缩算法标识" tabindex="-1">压缩算法标识 <a class="header-anchor" href="#压缩算法标识" aria-label="Permalink to “压缩算法标识”">​</a></h2><p>配置字节 0 的 bits 0–1 指定算法：</p><table tabindex="0"><thead><tr><th>编码</th><th>算法</th><th>默认</th></tr></thead><tbody><tr><td><code>00</code></td><td>LZMA</td><td>默认</td></tr><tr><td><code>01</code></td><td>Brotli</td><td></td></tr><tr><td><code>10</code></td><td>Deflate</td><td></td></tr><tr><td><code>11</code></td><td>保留</td><td>实现应回退为 LZMA</td></tr></tbody></table><blockquote><p><strong>约束</strong>：当算法不是 LZMA 时，b2–b3（LZMA Dict）必须为 <code>00</code>。</p></blockquote><h2 id="算法参数" tabindex="-1">算法参数 <a class="header-anchor" href="#算法参数" aria-label="Permalink to “算法参数”">​</a></h2><h3 id="lzma" tabindex="-1">LZMA <a class="header-anchor" href="#lzma" aria-label="Permalink to “LZMA”">​</a></h3><ul><li>格式：<code>lzma:FORMAT_ALONE</code>（独立的 LZMA 流，无容器头）</li><li>压缩等级：9（最大压缩）</li><li>LZMA 属性：lc=3, lp=0, pb=2</li><li>字典大小由配置字节 b2–b3 控制：</li></ul><table tabindex="0"><thead><tr><th>编码</th><th>字典大小</th><th>位移</th></tr></thead><tbody><tr><td><code>00</code></td><td>32 MiB</td><td><code>1 &lt;&lt; 25</code></td></tr><tr><td><code>01</code></td><td>64 MiB</td><td><code>1 &lt;&lt; 26</code></td></tr><tr><td><code>10</code></td><td>128 MiB</td><td><code>1 &lt;&lt; 27</code></td></tr><tr><td><code>11</code></td><td>256 MiB</td><td><code>1 &lt;&lt; 28</code></td></tr></tbody></table><h3 id="brotli" tabindex="-1">Brotli <a class="header-anchor" href="#brotli" aria-label="Permalink to “Brotli”">​</a></h3><ul><li>压缩质量：11（Brötli 最大级别）</li><li>使用默认窗口大小</li></ul><h3 id="deflate" tabindex="-1">Deflate <a class="header-anchor" href="#deflate" aria-label="Permalink to “Deflate”">​</a></h3><ul><li>模式：raw deflate（<code>wbits = -15</code>，无 zlib/gzip 头）</li><li>压缩等级：9</li></ul>',14)])])}const f=e(o,[["render",r]]);export{p as __pageData,f as default};
